\ref{examples-defos-example-rings}.

\href{https://stacks.math.columbia.edu/tag/0E3U}{\texttt{Stacks tag 0E3U}}


Example \ref{examples-defos-example-schemes-morphisms}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_{X \to Y}$ is a deformation category
for any morphism of schemes $X \to Y$ over $k$.

\href{https://stacks.math.columbia.edu/tag/0E3V}{\texttt{Stacks tag 0E3V}}


In Example \ref{examples-defos-example-schemes} let $f : X \to Y$ be a morphism of schemes
over $k$. There is a canonical exact sequence of $k$-vector spaces
$$
\begin{array}{cccc}0 \longrightarrow & \text{Inf}(\Deformationcategory_{X \to Y}) \longrightarrow & \text{Inf}(\Deformationcategory_X \times \Deformationcategory_Y) \longrightarrow & \text{Der}_k(\mathcal{O}_Y, f_*\mathcal{O}_X) \swarrow \\  & T\Deformationcategory_{X \to Y} \longrightarrow & T(\Deformationcategory_X \times \Deformationcategory_Y) \longrightarrow & \text{Ext}^1_{\mathcal{O}_X}(Lf^*\NL_{Y/k}, \mathcal{O}_X)\end{array}
$$

\href{https://stacks.math.columbia.edu/tag/0E40}{\texttt{Stacks tag 0E40}}


Example \ref{examples-defos-example-spaces}
satisfies the Rim-Schlessinger condition (RS).
In particular, $\Deformationcategory_X$ is a deformation category
for any algebraic space $X$ over $k$.

\href{https://stacks.math.columbia.edu/tag/0DZ5}{\texttt{Stacks tag 0DZ5}}


In Example \ref{examples-defos-example-rings} let $P$ be a $k$-algebra.
Let $J \subset P$ be an ideal.
Denote $P^\wedge$ the $J$-adic completion. If
\begin{enumerate}
\item $k \to P$ is of finite type, and
\item $\Spec(P) \to \Spec(k)$ is smooth on the complement of $V(J)$.
\end{enumerate}
then the functor between deformation categories of
Lemma \ref{examples-defos-lemma-completion}
$$
\Deformationcategory_P \longrightarrow \Deformationcategory_{P^\wedge}
$$
is smooth and induces an isomorphism on tangent spaces.

\href{https://stacks.math.columbia.edu/tag/0DZ9}{\texttt{Stacks tag 0DZ9}}


In Example \ref{examples-defos-example-rings} let $P$ be a $k$-algebra.
Let $S \subset P$ be a multiplicative subset. If
\begin{enumerate}
\item $k \to P$ is of finite type, and
\item $\Spec(P) \to \Spec(k)$ is smooth at all points of
$V(g)$ for all $g \in S$.
\end{enumerate}
then the functor between deformation categories of
Lemma \ref{examples-defos-lemma-localization}
$$
\Deformationcategory_P \longrightarrow \Deformationcategory_{S^{-1}P}
$$
is smooth and induces an isomorphism on tangent spaces.

\href{https://stacks.math.columbia.edu/tag/0DZD}{\texttt{Stacks tag 0DZD}}


In Example \ref{examples-defos-example-rings} let $P$ be a $k$-algebra.
Let $J \subset P$ be an ideal.
Denote $(P^h, J^h)$ the henselization of the pair $(P, J)$. If
\begin{enumerate}
\item $k \to P$ is of finite type, and
\item $\Spec(P) \to \Spec(k)$ is smooth on the complement of $V(J)$,
\end{enumerate}
then the functor between deformation categories of
Lemma \ref{examples-defos-lemma-henselization}
$$
\Deformationcategory_P \longrightarrow \Deformationcategory_{P^h}
$$
is smooth and induces an isomorphism on tangent spaces.

\href{https://stacks.math.columbia.edu/tag/0DZQ}{\texttt{Stacks tag 0DZQ}}


In Example \ref{examples-defos-example-schemes} let $X$ be a scheme over $k$. Assume
\begin{enumerate}
\item $X$ is separated, finite type over $k$ and $\dim(X) \leq 1$,
\item $X$ is a local complete intersection over $k$, and
\item $X \to \Spec(k)$ is smooth except at finitely many points.
\end{enumerate}
Then $\Deformationcategory_X$ is unobstructed.

\href{https://stacks.math.columbia.edu/tag/0E7Z}{\texttt{Stacks tag 0E7Z}}


Let $k$ be a field and let $X$ be a scheme over $k$. Assume
\begin{enumerate}
\item $X$ is separated, finite type over $k$ and $\dim(X) \leq 1$,
\item $X$ is a local complete intersection over $k$, and
\item $X \to \Spec(k)$ is smooth except at finitely many points.
\end{enumerate}
Then there exists a flat, separated, finite type morphism $Y \to \Spec(k[[t]])$
whose generic fibre is smooth and whose special fibre is
isomorphic to $X$.

\href{https://stacks.math.columbia.edu/tag/08S6}{\texttt{Stacks tag 08S6}}


If $A \to B$ is a local complete intersection ring map, then
there exists a solution to (\ref{equation-to-solve}).

\href{https://stacks.math.columbia.edu/tag/08KZ}{\texttt{Stacks tag 08KZ}}


A morphism of thickenings $(f, f')$ is given by a commutative diagram
\begin{equation}
\label{equation-morphism-thickenings}
\vcenter{
\begin{array}{cc}(X, \mathcal{O}_X) \underset{i}{\longrightarrow}\underset{f}{\downarrow} & (X', \mathcal{O}_{X'}) \overset{f'}{\downarrow} \\ (S, \mathcal{O}_S) \overset{t}{\longrightarrow} & (S', \mathcal{O}_{S'})\end{array}
}
\end{equation}
of ringed spaces whose horizontal arrows are thickenings. In this
situation we set
$\mathcal{I} = \Ker(i^\sharp) \subset \mathcal{O}_{X'}$ and
$\mathcal{J} = \Ker(t^\sharp) \subset \mathcal{O}_{S'}$.
As $f = f'$ on underlying topological spaces we will identify
the (topological) pullback functors $f^{-1}$ and $(f')^{-1}$.
Observe that $(f')^\sharp : f^{-1}\mathcal{O}_{S'} \to \mathcal{O}_{X'}$
induces in particular a map $f^{-1}\mathcal{J} \to \mathcal{I}$
and therefore a map of $\mathcal{O}_{X'}$-modules
$$
(f')^*\mathcal{J} \longrightarrow \mathcal{I}
$$
If $i$ and $t$ are first order thickenings, then
$(f')^*\mathcal{J} = f^*\mathcal{J}$ and the map above becomes a
map $f^*\mathcal{J} \to \mathcal{I}$.

\href{https://stacks.math.columbia.edu/tag/08L1}{\texttt{Stacks tag 08L1}}



In Situation \ref{defos-situation-morphism-thickenings} we say that $(f, f')$ is a
{\it strict morphism of thickenings}
if the map $(f')^*\mathcal{J} \longrightarrow \mathcal{I}$ is surjective.

\href{https://stacks.math.columbia.edu/tag/08U8}{\texttt{Stacks tag 08U8}}


Assume given a commutative diagram of morphisms of ringed spaces
\begin{equation}
\label{equation-huge-1}
\vcenter{
\begin{array}{ccc} & (X_2, \mathcal{O}_{X_2}) \underset{i_2}{\longrightarrow}\underset{f_2}{\downarrow}\underset{g}{\swarrow} & (X'_2, \mathcal{O}_{X'_2}) \overset{f'_2}{\downarrow} \\  & (S_2, \mathcal{O}_{S_2}) \overset{t_2}{\longrightarrow}\swarrow & (S'_2, \mathcal{O}_{S'_2}) \swarrow \\ (X_1, \mathcal{O}_{X_1}) \underset{i_1}{\longrightarrow}\underset{f_1}{\downarrow} & (X'_1, \mathcal{O}_{X'_1}) \overset{f'_1}{\downarrow} &  \\ (S_1, \mathcal{O}_{S_1}) \overset{t_1}{\longrightarrow} & (S'_1, \mathcal{O}_{S'_1}) & \end{array}
}
\end{equation}
whose horizontal arrows are first order thickenings. Set
$\mathcal{G}_j = \Ker(i_j^\sharp)$ and assume given
a $g$-map $\nu : \mathcal{G}_1 \to \mathcal{G}_2$ of modules
giving rise to the commutative diagram
\begin{equation}
\label{equation-huge-2}
\vcenter{
\begin{array}{cccccc} & 0 \longrightarrow & \mathcal{G}_2 \longrightarrow & \mathcal{O}_{X'_2} \longrightarrow & \mathcal{O}_{X_2} \longrightarrow & 0 \\  & 0 \longrightarrow & \mathcal{J}_2 \underset{c_2}{\uparrow}\longrightarrow & \mathcal{O}_{S'_2} \uparrow\longrightarrow & \mathcal{O}_{S_2} \uparrow\longrightarrow & 0 \\ 0 \longrightarrow & \mathcal{G}_1 \nearrow\longrightarrow & \mathcal{O}_{X'_1} \longrightarrow & \mathcal{O}_{X_1} \nearrow\longrightarrow & 0 &  \\ 0 \longrightarrow & \mathcal{J}_1 \nearrow\overset{c_1}{\uparrow}\longrightarrow & \mathcal{O}_{S'_1} \nearrow\uparrow\longrightarrow & \mathcal{O}_{S_1} \nearrow\uparrow\longrightarrow & 0 & \end{array}
}
\end{equation}
with front and back solutions to (\ref{equation-to-solve-ringed-spaces}).
\begin{enumerate}
\item There exist a canonical element in
$\Ext^1_{\mathcal{O}_{X_2}}(Lg^*\NL_{X_1/S_1}, \mathcal{G}_2)$
whose vanishing is a necessary and sufficient condition for the existence
of a morphism of ringed spaces $X'_2 \to X'_1$ fitting into
(\ref{equation-huge-1}) compatibly with $\nu$.
\item If there exists a morphism $X'_2 \to X'_1$ fitting into
(\ref{equation-huge-1}) compatibly with $\nu$ the set of all such morphisms
is a principal homogeneous space under
$$
\Hom_{\mathcal{O}_{X_1}}(\Omega_{X_1/S_1}, g_*\mathcal{G}_2) =
\Hom_{\mathcal{O}_{X_2}}(g^*\Omega_{X_1/S_1}, \mathcal{G}_2) =
\Ext^0_{\mathcal{O}_{X_2}}(Lg^*\NL_{X_1/S_1}, \mathcal{G}_2).
$$
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/08M7}{\texttt{Stacks tag 08M7}}


A morphism of thickenings of ringed topoi $(f, f')$
is given by a commutative diagram
\begin{equation}
\label{equation-morphism-thickenings-ringed-topoi}
\vcenter{
\begin{array}{cc}(\Sh(\mathcal{C}), \mathcal{O}) \underset{i}{\longrightarrow}\underset{f}{\downarrow} & (\Sh(\mathcal{D}), \mathcal{O}') \overset{f'}{\downarrow} \\ (\Sh(\mathcal{B}), \mathcal{O}_\mathcal{B}) \overset{t}{\longrightarrow} & (\Sh(\mathcal{B}'), \mathcal{O}_{\mathcal{B}'})\end{array}
}
\end{equation}
of ringed topoi whose horizontal arrows are thickenings. In this
situation we set
$\mathcal{I} = \Ker(i^\sharp) \subset \mathcal{O}'$ and
$\mathcal{J} = \Ker(t^\sharp) \subset \mathcal{O}_{\mathcal{B}'}$.
As $f = f'$ on underlying topoi we will identify
the pullback functors $f^{-1}$ and $(f')^{-1}$.
Observe that
$(f')^\sharp : f^{-1}\mathcal{O}_{\mathcal{B}'} \to \mathcal{O}'$
induces in particular a map $f^{-1}\mathcal{J} \to \mathcal{I}$
and therefore a map of $\mathcal{O}'$-modules
$$
(f')^*\mathcal{J} \longrightarrow \mathcal{I}
$$
If $i$ and $t$ are first order thickenings, then
$(f')^*\mathcal{J} = f^*\mathcal{J}$ and the map above becomes a
map $f^*\mathcal{J} \to \mathcal{I}$.

\href{https://stacks.math.columbia.edu/tag/08M9}{\texttt{Stacks tag 08M9}}



In Situation \ref{defos-situation-morphism-thickenings-ringed-topoi}
we say that $(f, f')$ is a {\it strict morphism of thickenings}
if the map $(f')^*\mathcal{J} \longrightarrow \mathcal{I}$ is surjective.

\href{https://stacks.math.columbia.edu/tag/08UG}{\texttt{Stacks tag 08UG}}


Assume given a commutative diagram of morphisms ringed topoi
\begin{equation}
\label{equation-huge-1-ringed-topoi}
\vcenter{
\begin{array}{ccc} & (\Sh(\mathcal{C}_2), \mathcal{O}_2) \underset{i_2}{\longrightarrow}\underset{f_2}{\downarrow}\underset{g}{\swarrow} & (\Sh(\mathcal{C}'_2), \mathcal{O}'_2) \overset{f'_2}{\downarrow} \\  & (\Sh(\mathcal{B}_2), \mathcal{O}_{\mathcal{B}_2}) \overset{t_2}{\longrightarrow}\swarrow & (\Sh(\mathcal{B}'_2), \mathcal{O}_{\mathcal{B}'_2}) \swarrow \\ (\Sh(\mathcal{C}_1), \mathcal{O}_1) \underset{i_1}{\longrightarrow}\underset{f_1}{\downarrow} & (\Sh(\mathcal{C}'_1), \mathcal{O}'_1) \overset{f'_1}{\downarrow} &  \\ (\Sh(\mathcal{B}_1), \mathcal{O}_{\mathcal{B}_1}) \overset{t_1}{\longrightarrow} & (\Sh(\mathcal{B}'_1), \mathcal{O}_{\mathcal{B}'_1}) & \end{array}
}
\end{equation}
whose horizontal arrows are first order thickenings. Set
$\mathcal{G}_j = \Ker(i_j^\sharp)$ and assume given a
map of $g^{-1}\mathcal{O}_1$-modules
$\nu : g^{-1}\mathcal{G}_1 \to \mathcal{G}_2$
giving rise to the commutative diagram
\begin{equation}
\label{equation-huge-2-ringed-topoi}
\vcenter{
\begin{array}{cccccc} & 0 \longrightarrow & \mathcal{G}_2 \longrightarrow & \mathcal{O}'_2 \longrightarrow & \mathcal{O}_2 \longrightarrow & 0 \\  & 0 \longrightarrow & f_2^{-1}\mathcal{J}_2 \underset{c_2}{\uparrow}\longrightarrow & f_2^{-1}\mathcal{O}_{\mathcal{B}'_2} \uparrow\longrightarrow & f_2^{-1}\mathcal{O}_{\mathcal{B}_2} \uparrow\longrightarrow & 0 \\ 0 \longrightarrow & \mathcal{G}_1 \nearrow\longrightarrow & \mathcal{O}'_1 \longrightarrow & \mathcal{O}_1 \nearrow\longrightarrow & 0 &  \\ 0 \longrightarrow & f_1^{-1}\mathcal{J}_1 \nearrow\overset{c_1}{\uparrow}\longrightarrow & f_1^{-1}\mathcal{O}_{\mathcal{B}'_1} \nearrow\uparrow\longrightarrow & f_1^{-1}\mathcal{O}_{\mathcal{B}_1} \nearrow\uparrow\longrightarrow & 0 & \end{array}
}
\end{equation}
with front and back solutions to (\ref{equation-to-solve-ringed-topoi}).
(The north-north-west arrows are maps on $\mathcal{C}_2$ after applying
$g^{-1}$ to the source.)
\begin{enumerate}
\item There exist a canonical element in
$\Ext^1_{\mathcal{O}_2}(
Lg^*\NL_{\mathcal{O}_1/\mathcal{O}_{\mathcal{B}_1}}, \mathcal{G}_2)$
whose vanishing is a necessary and sufficient condition for the existence
of a morphism of ringed topoi
$(\Sh(\mathcal{C}'_2), \mathcal{O}'_2) \to
(\Sh(\mathcal{C}'_1), \mathcal{O}'_1)$ fitting into
(\ref{equation-huge-1-ringed-topoi}) compatibly with $\nu$.
\item If there exists a morphism
$(\Sh(\mathcal{C}'_2), \mathcal{O}'_2) \to
(\Sh(\mathcal{C}'_1), \mathcal{O}'_1)$
fitting into
(\ref{equation-huge-1-ringed-topoi}) compatibly with $\nu$ the set
of all such morphisms is a principal homogeneous space under
$$
\Hom_{\mathcal{O}_1}(
\Omega_{\mathcal{O}_1/\mathcal{O}_{\mathcal{B}_1}}, g_*\mathcal{G}_2) =
\Hom_{\mathcal{O}_2}(
g^*\Omega_{\mathcal{O}_1/\mathcal{O}_{\mathcal{B}_1}}, \mathcal{G}_2) =
\Ext^0_{\mathcal{O}_2}(
Lg^*\NL_{\mathcal{O}_1/\mathcal{O}_{\mathcal{B}_1}}, \mathcal{G}_2).
$$
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/06GE}{\texttt{Stacks tag 06GE}}


Let $f: B \to A$ be a surjective ring map in $\mathcal{C}_\Lambda$.
Then $f$ can be factored as a composition of small extensions.

\href{https://stacks.math.columbia.edu/tag/06S3}{\texttt{Stacks tag 06S3}}


Let $A \to B$ be a ring map in $\mathcal{C}_\Lambda$.
The following are equivalent
\begin{enumerate}
\item $f$ is surjective,
\item $\mathfrak m_A/\mathfrak m_A^2 \to \mathfrak m_B/\mathfrak m_B^2$
is surjective, and
\item $\mathfrak m_A/(\mathfrak m_\Lambda A + \mathfrak m_A^2)
\to \mathfrak m_B/(\mathfrak m_\Lambda B + \mathfrak m_B^2)$ is surjective.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/06GF}{\texttt{Stacks tag 06GF}}


Let $f: B \to A$ be a ring map in $\mathcal{C}_\Lambda$.  We say $f$
is an {\it essential surjection} if it has the following properties:
\begin{enumerate}
\item $f$ is surjective.
\item If $g: C \to B$ is a ring map in $\mathcal{C}_\Lambda$ such that
$f \circ g$ is surjective, then $g$ is surjective.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/06GW}{\texttt{Stacks tag 06GW}}


Let $\Lambda$ be a Noetherian ring and let $\Lambda \to k$ be a finite
ring map where $k$ is a field. We define {\it $\widehat{\mathcal{C}}_\Lambda$}
to be the category with
\begin{enumerate}
\item objects are pairs $(R, \varphi)$ where $R$ is a Noetherian complete
local $\Lambda$-algebra and where $\varphi : R/\mathfrak m_R \to k$ is a
$\Lambda$-algebra isomorphism, and
\item morphisms $f : (S, \psi) \to (R, \varphi)$ are local $\Lambda$-algebra
homomorphisms such that $\varphi \circ (f \bmod \mathfrak m) = \psi$.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/06H1}{\texttt{Stacks tag 06H1}}


The category $\widehat{\mathcal{C}}_\Lambda$ admits coproducts
of pairs of objects.

\href{https://stacks.math.columbia.edu/tag/06SC}{\texttt{Stacks tag 06SC}}


Let $S$ be an object of $\widehat{\mathcal{C}}_\Lambda$.
Then $\dim_k \text{Der}_\Lambda(S, k) < \infty$.

\href{https://stacks.math.columbia.edu/tag/06H6}{\texttt{Stacks tag 06H6}}


In the situation above, $\widehat{\mathcal{F}}_\mathcal{I}(R)$ is equivalent
to the category $\widehat{\mathcal{F}}(R)$.

\href{https://stacks.math.columbia.edu/tag/06HM}{\texttt{Stacks tag 06HM}}


Let $\varphi : \mathcal{F} \to \mathcal{G}$ and $\psi : \mathcal{G}
\to \mathcal{H}$ be morphisms of categories cofibered in groupoids over
$\mathcal{C}_\Lambda$.
\begin{enumerate}
\item If $\varphi$ and $\psi$ are smooth, then $\psi \circ \varphi$ is smooth.
\item If $\varphi$ is essentially surjective and $\psi \circ \varphi$ is
smooth, then $\psi$ is smooth.
\item If $\mathcal{G}' \to \mathcal{G}$ is a morphism of categories
cofibered in groupoids and $\varphi$ is smooth, then
$\mathcal{F} \times_\mathcal{G} \mathcal{G}' \to \mathcal{G}'$ is smooth.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/06HP}{\texttt{Stacks tag 06HP}}


Let $p : \mathcal{F} \to \mathcal{C}_\Lambda$ be a category cofibered in
groupoids. We say $\mathcal{F}$ is {\it smooth} or {\it unobstructed}
if its structure morphism $p$ is smooth
in the sense of Definition \ref{formal-defos-definition-smooth-morphism}.

\href{https://stacks.math.columbia.edu/tag/0DYL}{\texttt{Stacks tag 0DYL}}


Let $R \in \Ob(\widehat{\mathcal{C}}_\Lambda)$. The following are
equivalent
\begin{enumerate}
\item $\underline{R}|_{\mathcal{C}_\Lambda}$ is smooth,
\item $\Lambda \to R$ is formally smooth in the $\mathfrak m_R$-adic topology,
\item $\Lambda \to R$ is flat and $R \otimes_\Lambda k'$ is
geometrically regular over $k'$, and
\item $\Lambda \to R$ is flat and $k' \to R \otimes_\Lambda k'$ is
formally smooth in the $\mathfrak m_R$-adic topology.
\end{enumerate}
In the classical case, these are also equivalent to
\begin{enumerate}
\item[(5)] $R$ is isomorphic to $\Lambda[[x_1, \ldots, x_n]]$
for some $n$.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/0DZK}{\texttt{Stacks tag 0DZK}}


Let $\mathcal{F}$ be a predeformation category.
Let $\xi$ be a versal formal object of $\mathcal{F}$ lying over
$R \in \Ob(\widehat{\mathcal{C}}_\Lambda)$. The following are
equivalent
\begin{enumerate}
\item $\mathcal{F}$ is unobstructed, and
\item $\Lambda \to R$ is formally smooth in the $\mathfrak m_R$-adic topology.
\end{enumerate}
In the classical case these are also equivalent to
\begin{enumerate}
\item[(3)] $R \cong \Lambda[[x_1, \ldots, x_n]]$ for some $n$.\
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/06SM}{\texttt{Stacks tag 06SM}}


There exists an $R \in \Ob(\widehat{\mathcal{C}}_\Lambda)$
such that the equivalent conditions of Lemma \ref{formal-defos-lemma-smooth}
hold and moreover $H_1(L_{k/\Lambda}) = \mathfrak m_R/\mathfrak m_R^2$
and $\Omega_{R/\Lambda} \otimes_R k = \Omega_{k/\Lambda}$.

\href{https://stacks.math.columbia.edu/tag/06HW}{\texttt{Stacks tag 06HW}}


Let $\mathcal{F}$ be a category cofibered in groupoids over $\mathcal
C_\Lambda$. We define {\it conditions (S1) and (S2)}
on $\mathcal{F}$ as follows:
\begin{enumerate}
\item[(S1)] Every diagram in $\mathcal{F}$
$$
\vcenter{
\begin{array}{cc} & x_2 \downarrow \\ x_1 \longrightarrow & x\end{array}
}
\quad\text{lying over}\quad
\vcenter{
\begin{array}{cc} & A_2 \downarrow \\ A_1 \longrightarrow & A\end{array}
}
$$
in $\mathcal{C}_\Lambda$ with $A_2 \to A$ surjective can be completed
to a commutative diagram
$$
\vcenter{
\begin{array}{cc}y \longrightarrow\downarrow & x_2 \downarrow \\ x_1 \longrightarrow & x\end{array}
}
\quad\text{lying over}\quad
\vcenter{
\begin{array}{cc}A_1 \times_A A_2 \longrightarrow\downarrow & A_2 \downarrow \\ A_1 \longrightarrow & A.\end{array}
}
$$
\item[(S2)]
The condition of (S1) holds for diagrams in $\mathcal{F}$ lying over
a diagram in $\mathcal{C}_\Lambda$ of the form
$$
\begin{array}{cc} & k[\epsilon] \downarrow \\ A  \longrightarrow & k.\end{array}
$$
Moreover, if we have two commutative diagrams in $\mathcal{F}$
$$
\vcenter{
\begin{array}{cc}y \underset{c}{\longrightarrow}\underset{a}{\downarrow} & x_\epsilon \overset{e}{\downarrow} \\ x \overset{d}{\longrightarrow} & x_0\end{array}
}
\quad\text{and}\quad
\vcenter{
\begin{array}{cc}y' \underset{c'}{\longrightarrow}\underset{a'}{\downarrow} & x_\epsilon \overset{e}{\downarrow} \\ x \overset{d}{\longrightarrow} & x_0\end{array}
}
\quad\text{lying over}\quad
\vcenter{
\begin{array}{cc}A \times_k k[\epsilon] \longrightarrow\downarrow & k[\epsilon] \downarrow \\ A  \longrightarrow & k\end{array}
}
$$
then there exists a morphism $b : y \to y'$ in
$\mathcal{F}(A \times_k k[\epsilon])$ such that $a = a' \circ b$.
\end{enumerate}

\href{https://stacks.math.columbia.edu/tag/06SQ}{\texttt{Stacks tag 06SQ}}


Let $\mathcal{F}$ be a category cofibered in groupoids over
$\mathcal{C}_\Lambda$. Let $x_0 \in \Ob(\mathcal{F}(k))$.
Let $\mathcal{F}_{x_0}$ be the category cofibred in groupoids over
$\mathcal{C}_\Lambda$ constructed in
